#!/usr/bin/env python3
"""sen0414_lineage_owner_note v1_1_0 - records the Owner's statement of 2026-11-01 11:52 Istanbul (relayed) with its consequences for the exam lineage, the new story of the design revision (Proposed, waiting for one owner answer),
the controller's measurements of the sheet and of the chapters 1 to 8 decks. A NEW file over v1_0_0; ONE new register version.   Usage: sen0414_lineage_owner_note_v1_1_0.py record"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0414_lineage_standard_v1_2_0 as W
lit = W.lit
assert sys.argv[1:2] == ["record"], __doc__
WORD = ("OWNER STATEMENT of 2026-11-01 at 11:52 Istanbul (08:52 UTC), relayed by the course coordinator and recorded as relayed: 'I need the PPT slides and interactive HTML files for both courses. Midterm scope: ... SEN0414: Chapter 1-4 & 5-8, the MS Word midterm exams, answer sheets. I will give you some details about the exam questions, as I made some interactive sessions during the class ... "
        "The examinations should be developed to fit into 4 pages in total, to print in 2 pages, easy to read and assess, but using various techniques, including calculations, ordering, etc, that can be helpful to replace hand writing answers.' "
        "Read as: (1) the paper, its key and the answer sheet are delivered as .docx; (2) the whole examination is 4 pages printed double-sided on 2 sheets (the lineage agent's reading, from his words 'in total'; the answer sheet counts inside the 4 pages); (3) '1-4 & 5-8' may include chapter 5 (Debugging), which his statement of 2026-10-29 excluded: ONE question to him, pending; (4) he will send details of the question styles of his class sessions: these are seeds, never copied; (5) the slides and the pages of chapters 1 to 8 are delivered to him.")
EFFECT = ("CONSEQUENCES recorded by the lineage agent (2026-11-01): (a) the revised design v1_1_0 stays as committed; a new design file v1_2_0 is needed (story ST4_DesignRev2, Proposed) for the .docx outputs, the 4-page total and, if he answers so, chapter 5. "
          "(b) The pages: measured with the SEN0401 sheet module (log control_sheet_pages_by_units): a sheet of up to 40 single-choice rows is one page and 45 rows are two pages; the present blueprint's 54 sheet units (choice 21, match 10, order 8, bank 15 with two rows each) are two pages; the paper was estimated at 393 lines, 3.5 pages at 112 lines a page (an estimate, not a measure: no renderer exists yet). "
          "So 30 items fit in 4 pages in total only if the sheet becomes one page (fewer two-row bank units and match units) and the paper becomes 3 pages (about 9 point type, 134 lines a page, or shorter listings); with the sheet left at two pages the paper has 2 pages (224 lines at 10 point, 268 at 9 point) and holds about 16 items at 10 point or 19 at 9 point at the present length of 12.3 lines an item. "
          "(c) Chapter 5: the critical points exist only for chapters 1 to 4 and 6 to 8; including chapter 5 needs its critical points, a pool, a 4,4,4,4,3,4,4,3 style split instead of 4,5,5,5,4,4,3, and a new item validator (its chapter list is fixed) and design; the near-copy rule already reads chapter 5 seeds. "
          "(d) The item pool briefs (r6) are held until his question styles arrive and the design v1_2_0 fixes the item length and the chapter list; the engine repair TK4_Engine_Bloom (brief r7) does not depend on these and stands.")
DECKS = ("MEASUREMENT of the lecture decks of chapters 1 to 8 with the new deck standard check v1_1_0 (controller's run 2026-11-01, logs in 08-tooling/control-u8-logs/deckcheck_ch01_08): chapter 8 PASS 13 of 13; chapter 1 FAIL D3 M1; chapter 3 FAIL D3 M1; chapter 5 FAIL D3 M1; chapter 2 FAIL D3 D5 M1; chapter 4 FAIL D3 D5 M1; chapter 6 FAIL D3 D5 M1; chapter 7 FAIL D3 D5 M1. "
         "The decks of chapters 1 to 7 exist but do not meet the written standard as the new check measures it (the retrofit stories ST_Plan_Retrofit_Ch01 to Ch05 and the chapter 6 and 7 work are the register's way to bring them up); the pages of chapters 1 to 7 are older than the page standard of chapter 8 (v9_92_1). Delivering them as they are is delivering unmet standard; this is stated to the Owner.")
src = W.newest(); t = open(src, encoding="utf-8").read(); n = W.now(); L = []
for k in ("Mission4", "Scope4", "ST4_Papers", "ST4_DesignRev"):
    assert "\nex:%s a backlog:" % k in t, k
    L.append("ex:%s backlog:hasAuditNote %s .\n" % (k, lit(WORD))); L.append("ex:%s backlog:hasAuditNote %s .\n" % (k, lit(EFFECT)))
L.append("ex:Obj2_StdDecks backlog:hasAuditNote %s .\nex:Lineage2 backlog:hasAuditNote %s .\n" % (lit(DECKS), lit(DECKS)))
L.append('\nex:ST4_DesignRev2 a backlog:Story ; rdfs:label "The design of the papers revised to the Owner\'s statements of 2026-11-01: .docx outputs, four pages in total, the chapter list"@en ; backlog:hasIdentifier "ST4_DesignRev2" ;\n    backlog:hasTitle "The design of the papers revised to the Owner\'s statements of 2026-11-01" ;\n'
         '    backlog:belongsToLineage ex:Lineage4 ; backlog:responsible ex:Executor_ClaudeCodeSession ; backlog:admittedByOutput ex:Out4_Backlog ;\n    backlog:hasInvestmentCategory backlog:Cat_NewCapability ;\n'
         '    backlog:asRole "SEN0414 instructor" ; backlog:wantsCapability "a design v1_2_0 of the printed papers whose paper, key and answer sheet are .docx documents, whose whole examination is four pages printed double-sided, with a measured page budget per item type and the chapter list the Owner decides" ; backlog:soThat "the midterm prints on two sheets, is editable in MS Word, and is easy to read and to assess" ;\n'
         '    backlog:satisfiesDeliverable ex:Del4_Papers ; backlog:pursuesObjective ex:Obj4_PapersBuilt ; backlog:hasAcceptanceCriterion ex:AC4_Controlled ;\n    backlog:coversEntity ex:DE4_ExamPaper ; backlog:coversStage backlog:Stage_Creation ;\n    backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasApplicableConcern backlog:Concern_Data ;\n'
         '    backlog:hasState backlog:Proposed ;\n    backlog:notYetScoreable true ; backlog:hasScoreabilityReason "Waits for the Owner\'s answer on chapter 5 and for the question styles of his class sessions; scored and decomposed into tasks when they arrive." ;\n    backlog:hasAuditNote %s .\n' % lit(EFFECT))
L.append("ex:EP4_Engine backlog:decomposesInto ex:ST4_DesignRev2 .\nex:Obj4_PapersBuilt backlog:metricMovableBy ex:ST4_DesignRev2 .\n")
print(os.path.basename(W.write_new(src, t + "\n" + "".join(L), "The Owner's statement of 11:52 Istanbul (2026-11-01) recorded with its consequences: .docx for paper, key and sheet, four pages in total, chapter 5 pending one question; the design-revision story ST4_DesignRev2 admitted as Proposed; the measurements of the chapter 1 to 8 decks.")))
